<?php require_once __DIR__.'/includes/functions.php';if(!cart_data()){header('Location: /cart.php');exit;}$errors=[];$states=['AL','AK','AZ','AR','CA','CO','CT','DE','FL','GA','HI','ID','IL','IN','IA','KS','KY','LA','ME','MD','MA','MI','MN','MS','MO','MT','NE','NV','NH','NJ','NM','NY','NC','ND','OH','OK','OR','PA','RI','SC','SD','TN','TX','UT','VT','VA','WA','WV','WI','WY','DC'];if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){check_csrf();$fields=['first_name','last_name','email','phone','address','city','state','zip'];foreach($fields as $f){$v=trim((string)($_POST[$f]??''));if($v==='')$errors[$f]='Required';$_SESSION['checkout'][$f]=$v;}if(!filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL))$errors['email']='Enter a valid email';if(!in_array($_POST['state']??'',$states,true))$errors['state']='Choose a valid state';if(!preg_match('/^[0-9]{5}(-[0-9]{4})?$/',$_POST['zip']??''))$errors['zip']='Enter a valid ZIP code';if(!$errors)$_SESSION['checkout']['address2']=trim((string)($_POST['address2']??''));} $meta=page_meta('Checkout | iPhone Deals');require __DIR__.'/includes/header.php';$v=$_SESSION['checkout']??[];?>
<section class="wrap"><p class="eyebrow">SECURE CHECKOUT</p><h1 class="page-title">Shipping details</h1><p class="notice">Checkout is in setup mode. Payments are disabled until PayPal credentials are configured. No order will be placed by this demo.</p><?php if($errors)echo '<p class="notice">Please correct the highlighted or missing fields.</p>';?><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><?php $labels=['first_name'=>'First name','last_name'=>'Last name','email'=>'Email','phone'=>'Phone','address'=>'Street address','address2'=>'Apartment / suite','city'=>'City','zip'=>'ZIP code'];foreach($labels as $key=>$lab):?><div class="form-field <?=$key==='address'||$key==='address2'?'span-2':''?>"><label for="<?=$key?>"><?=e($lab)?></label><input id="<?=$key?>" name="<?=$key?>" value="<?=e($v[$key]??'')?>" <?=$key==='email'?'type="email"':''?> <?=$key!=='address2'?'required':''?>"></div><?php endforeach;?><div class="form-field"><label for="state">State</label><select id="state" name="state" required><option value="">Select state</option><?php foreach($states as $st):?><option <?=$st===($v['state']??'')?'selected':''?>><?=$st?></option><?php endforeach;?></select></div><div class="form-field"><label>Country</label><input value="United States" readonly></div><div class="span-2"><h2>Order summary</h2><?php foreach(cart_data() as $i):?><div class="summary-line"><span><?=e($i['p']['name'])?> × <?=$i['qty']?></span><b><?=money($i['p']['price']*$i['qty'])?></b></div><?php endforeach;?><div class="summary-line"><b>Subtotal</b><b><?=money(cart_total())?></b></div><p class="muted">Shipping and tax are not configured in this demo. Configure real shipping and tax rules before accepting orders.</p><button class="button button-dark" disabled>PayPal checkout not configured</button></div></form></section><?php require __DIR__.'/includes/footer.php';?>
